import pytest

import duckdb


class TestUDFTransactionality:
    def test_type_coverage(self, duckdb_cursor):
        duckdb_cursor.execute("select * from range(4096)")
        assert duckdb_cursor.fetchone() == (0,)

        def my_func(x: str) -> int:
            return int(x)

        with pytest.raises(duckdb.ResourceInUseException, match="unfinished result from execute"):
            duckdb_cursor.create_function("test", my_func)

        assert duckdb_cursor.fetchone() == (1,)

import duckdb
import pandas as pd

try:
    import pyarrow as pa

    can_run = True
except Exception:
    can_run = False


class Test3654:
    def test_3654_pandas(self, duckdb_cursor):
        df1 = pd.DataFrame(
            {
                "id": [1, 1, 2],
            }
        )
        con = duckdb.connect()
        con.register("df1", df1)
        rel = con.view("df1")
        print(rel.fetchall())
        assert rel.fetchall() == [(1,), (1,), (2,)]

    def test_3654_arrow(self, duckdb_cursor):
        if not can_run:
            return

        df1 = pd.DataFrame(
            {
                "id": [1, 1, 2],
            }
        )
        table = pa.Table.from_pandas(df1)
        con = duckdb.connect()
        con.register("df1", table)
        rel = con.view("df1")
        print(rel.fetchall())
        assert rel.fetchall() == [(1,), (1,), (2,)]

# timestamp ms precision

from datetime import datetime

import numpy


class TestNumpyTimestampMilliseconds:
    def test_numpy_timestamp(self, duckdb_cursor):
        res = duckdb_cursor.execute("SELECT TIMESTAMP '2019-11-26 21:11:42.501' as test_time").fetchnumpy()
        assert res["test_time"] == numpy.datetime64("2019-11-26 21:11:42.501")


class TestTimestampMilliseconds:
    def test_numpy_timestamp(self, duckdb_cursor):
        res = duckdb_cursor.execute("SELECT TIMESTAMP '2019-11-26 21:11:42.501' as test_time").fetchone()[0]
        assert res == datetime.strptime("2019-11-26 21:11:42.501", "%Y-%m-%d %H:%M:%S.%f")

import json

import duckdb


def parsed(sql):
    tree = json.loads(duckdb.connect().execute("SELECT json_serialize_sql(?)", [sql]).fetchall()[0][0])
    return [without_locations(statement) for statement in tree["statements"]]


def without_locations(node):
    if isinstance(node, dict):
        return {k: without_locations(v) for k, v in node.items() if not k.startswith("query_location")}
    if isinstance(node, list):
        return [without_locations(v) for v in node]
    return node


class TestRAPIFunctions:
    def test_rapi_str_print(self, duckdb_cursor, capsys):
        res = duckdb_cursor.query("select 42::INT AS a, 84::BIGINT AS b")
        drawn = str(res)
        assert [name for name in res.columns if name in drawn] == ["a", "b"]
        assert "42" in drawn
        assert "84" in drawn
        res.show()
        assert capsys.readouterr().out.strip() == drawn.strip()

    def test_rapi_relation_sql_query(self):
        res = duckdb.table_function("range", [10])
        assert parsed(res.sql_query()) == parsed("SELECT * FROM range(10)")
        assert duckdb.sql(res.sql_query()).fetchall() == res.fetchall()
